-- 445: Original BrillaPrep WASSCE Core Mathematics sprint 2 beta questions, part 3 of 10 (batch wassce-core-math-sprint2-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_445_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_445_guard;
INSERT INTO _migration_445_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_011' AND NOT (q.topic_id IS 'topic_wcoremath_geometry' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'O is the centre of a circle; A, B and C are points on its circumference with C on the major arc AB. If angle AOB = 130°, calculate angle ACB.' AND q.question_type IS 'calculation' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '65°' AND q.explanation IS 'The angle subtended at the centre of a circle is twice the angle subtended at the circumference by the same arc. Since C lies on the major arc, angle ACB = 130° ÷ 2 = 65°. Answer: 65°.' AND q.difficulty IS 'medium' AND q.points IS '4' AND q.marks IS '2' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_011' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_445_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_012' AND NOT (q.topic_id IS 'topic_wcoremath_geometry' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The sum of the interior angles of a polygon is 1,260°. Calculate the number of sides of the polygon.' AND q.question_type IS 'calculation' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '9 sides' AND q.explanation IS 'A polygon with n sides has interior-angle sum (n − 2) × 180°. Setting (n − 2) × 180 = 1,260 gives n − 2 = 1,260 ÷ 180 = 7, so n = 9. Check: (9 − 2) × 180 = 7 × 180 = 1,260°, as required. Answer: the polygon has 9 sides.' AND q.difficulty IS 'hard' AND q.points IS '4' AND q.marks IS '2' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_012' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_445_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_013' AND NOT (q.topic_id IS 'topic_wcoremath_trigonometry' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A right-angled triangle has a hypotenuse of 13 cm and one side of 5 cm. Find the length of the third side.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 8 cm","B. 18 cm","C. 12 cm","D. √194 cm"]' AND q.correct_answer IS 'C' AND q.explanation IS 'By the theorem of Pythagoras, the third side is √(13² − 5²) = √(169 − 25) = √144 = 12 cm. (√194 cm comes from adding the squares, which applies only when both given sides are the shorter ones.) Therefore the correct answer is C: 12 cm.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_013' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_445_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_014' AND NOT (q.topic_id IS 'topic_wcoremath_trigonometry' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A ladder 10 m long leans against a vertical wall, making an angle of 60° with the horizontal ground. How far is the foot of the ladder from the wall?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 8.7 m","B. 10 m","C. 5√3 m","D. 5 m"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The distance from the wall is the side adjacent to the 60° angle, with the ladder as hypotenuse: 10 × cos 60° = 10 × 0.5 = 5 m. (10 sin 60° ≈ 8.7 m is the height reached up the wall, not the distance asked for.) Therefore the correct answer is D: 5 m.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_014' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_445_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_015' AND NOT (q.topic_id IS 'topic_wcoremath_trigonometry' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A kite is at the end of a taut string 50 m long that makes an angle of 30° with the horizontal. Calculate the height of the kite above the ground.' AND q.question_type IS 'calculation' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '25 m' AND q.explanation IS 'The height is the side opposite the 30° angle in the right-angled triangle, with the string as hypotenuse: h = 50 × sin 30° = 50 × 0.5 = 25 m. Answer: the kite is 25 m above the ground.' AND q.difficulty IS 'medium' AND q.points IS '4' AND q.marks IS '2' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_015' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s2_011', 'topic_wcoremath_geometry', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'O is the centre of a circle; A, B and C are points on its circumference with C on the major arc AB. If angle AOB = 130°, calculate angle ACB.', 'calculation', NULL, NULL, '65°', 'The angle subtended at the centre of a circle is twice the angle subtended at the circumference by the same arc. Since C lies on the major arc, angle ACB = 130° ÷ 2 = 65°. Answer: 65°.', 'medium', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s2_012', 'topic_wcoremath_geometry', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'The sum of the interior angles of a polygon is 1,260°. Calculate the number of sides of the polygon.', 'calculation', NULL, NULL, '9 sides', 'A polygon with n sides has interior-angle sum (n − 2) × 180°. Setting (n − 2) × 180 = 1,260 gives n − 2 = 1,260 ÷ 180 = 7, so n = 9. Check: (9 − 2) × 180 = 7 × 180 = 1,260°, as required. Answer: the polygon has 9 sides.', 'hard', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s2_013', 'topic_wcoremath_trigonometry', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'A right-angled triangle has a hypotenuse of 13 cm and one side of 5 cm. Find the length of the third side.', 'multiple_choice', NULL, '["A. 8 cm","B. 18 cm","C. 12 cm","D. √194 cm"]', 'C', 'By the theorem of Pythagoras, the third side is √(13² − 5²) = √(169 − 25) = √144 = 12 cm. (√194 cm comes from adding the squares, which applies only when both given sides are the shorter ones.) Therefore the correct answer is C: 12 cm.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Find', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s2_014', 'topic_wcoremath_trigonometry', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'A ladder 10 m long leans against a vertical wall, making an angle of 60° with the horizontal ground. How far is the foot of the ladder from the wall?', 'multiple_choice', NULL, '["A. 8.7 m","B. 10 m","C. 5√3 m","D. 5 m"]', 'D', 'The distance from the wall is the side adjacent to the 60° angle, with the ladder as hypotenuse: 10 × cos 60° = 10 × 0.5 = 5 m. (10 sin 60° ≈ 8.7 m is the height reached up the wall, not the distance asked for.) Therefore the correct answer is D: 5 m.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s2_015', 'topic_wcoremath_trigonometry', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'A kite is at the end of a taut string 50 m long that makes an angle of 30° with the horizontal. Calculate the height of the kite above the ground.', 'calculation', NULL, NULL, '25 m', 'The height is the side opposite the 30° angle in the right-angled triangle, with the string as hypotenuse: h = 50 × sin 30° = 50 × 0.5 = 25 m. Answer: the kite is 25 m above the ground.', 'medium', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_waec');
